const payload = $input.first().json;
const posts = payload?.data?.children || [];

const painKeywords = [
  'how to automate', 'looking for a tool', 'is there a bot',
  'any tool that', 'manual work', 'spend hours', 'sync between',
  'connect api', 'alternative to', 'need a script', 'scrape data'
];

const results = [];

for (const post of posts) {
  const data = post.data || {};
  const text = `${data.title || ''} ${data.selftext || ''}`.toLowerCase();

  const matchedPains = painKeywords.filter(kw => text.includes(kw));
  if (matchedPains.length === 0) continue;

  results.push({
    opportunity_id: `demand_reddit_${data.id}`,
    source: 'Reddit Public Signal',
    source_url: `https://reddit.com${data.permalink}`,
    discovered_at: new Date().toISOString(),
    title: `[DEMANDA] ${data.title}`,
    organization: `u/${data.author}`,
    opportunity_type: 'demand_signal',
    decision: 'CONSTRUIR_Y_VENDER',
    observed_data: {
      pain_statement: data.title,
      frustration_signals: matchedPains,
      upvotes: data.ups,
      num_comments: data.num_comments
    },
    estimated_data: {
      proposed_solution_type: 'Plantilla n8n / Script de integración / Bot',
      build_complexity: 'Baja a Media (<16h)',
      scalability_rating: 85,
      reusability_score: 90
    },
    overall_score: 80,
    reasoning: `Problema recurrente expresado por usuarios: ${matchedPains.join(', ')}`,
    next_action: 'Diseñar prototipo de solución y evaluar mercado de compradores similares.'
  });
}

return results.map(r => ({ json: r }));
